def _split_nul(text):
    """Split null-separated parser output (Perl unpack '(Z*)*'), dropping a
    single trailing empty produced by a terminating null.
    """
    parts = text.split("\0")
    if parts and parts[-1] == "":
        parts.pop()
    return parts


def _run_case(exe, name, json_bytes, error, tmp_path, env):
    """Run one inline case across all chunk sizes and check each result."""
    chunk = min(len(json_bytes), 64)
    fname = tmp_path / "inline.json"
    fname.write_bytes(json_bytes)
    proc = subprocess.run(
        exe + ["-r", str(chunk), str(fname)],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=env,
        check=False,
    )
    stdout = _split_nul(proc.stdout.decode("latin-1"))
    stderr = _split_nul(proc.stderr.decode("latin-1"))
    assert len(stdout) == chunk, "{}: stdout has correct number of entries".format(name)
    assert len(stderr) == chunk, "{}: stderr has correct number of entries".format(name)
    for i, size in enumerate(reversed(range(1, chunk + 1))):
        if error is not None:
            assert not re.search(
                "SUCCESS", stdout[i]
            ), "{}, chunk size {}: test fails".format(name, size)
            assert re.search(
                error, stderr[i]
            ), "{}, chunk size {}: correct error output".format(name, size)
        else:
            assert re.search(
                "SUCCESS", stdout[i]
            ), "{}, chunk size {}: test succeeds".format(name, size)
            assert stderr[i] == "", "{}, chunk size {}: no error output".format(
                name, size
            )


def test_002_inline(tmp_path, bindir):
    """Every inline JSON case parses correctly at all chunk sizes, all variants."""
    # Resolve the test_json_parser_incremental* binaries against the build's
    # bindir (they are not on the ambient PATH in a build-tree run).
    env = dict(os.environ)
    env["PATH"] = str(bindir) + os.pathsep + env.get("PATH", "")
    for exe in _EXES:
        for name, json_bytes, error in _CASES:
            _run_case(exe, name, json_bytes, error, tmp_path, env)
